"display: grid; grid-template-columns: 200px minmax(0, 1fr); gap: 28px\">\n<div class=\"portrait-col\" style=\"display: flex; flex-direction: column; gap: 14px\">\n<div class=\"portrait\" style=\"position: relative; width: 200px; height: 250px; border-radius: 14px; background: #EDE3D3; border: 1px solid rgba(33,28,24,.15); overflow: hidden\">\n<img src=\"/chanel.jpeg\" alt=\"Chanel Hicks-Gray\" style=\"position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; object-position: top; display: block\">\n<div class=\"scan\" style=\"opacity: .35\"></div>\n</div>\n<div style=\"display: flex; flex-direction: column; gap: 8px; font-size: 12px; line-height: 1.4\">\n<div style=\"display: flex; gap: 8px; align-items: center\"><span style=\"width: 6px; height: 6px; border-radius: 50%; background: #A9803A; flex-shrink: 0\"></span>Founder, Hicks Virtual Solutions LLC</div>\n<div style=\"display: flex; gap: 8px; align-items: center\"><span style=\"width: 6px; height: 6px; border-radius: 50%; background: #B8466E; flex-shrink: 0\"></span>Founder, Stackd Studios AI</div>\n</div>\n</div>\n<div style=\"display: flex; flex-direction: column; gap: 14px\">\n<div class=\"eyebrow\">Where it starts</div>\n<h2 class=\"serif\" style=\"margin: 0; font-size: 46px; line-height: 1\">The whole problem, <em style=\"color: #B8466E\">end to end.</em></h2>\n<p style=\"margin: 0; font-size: 14px; line-height: 1.65; color: #4A4038; text-wrap: pretty\">I started in psychology, studying how people make decisions, what drives behavior, and why the most logical solution isn’t always the one people choose. Every system I design is really a question: will a real person actually use this?</p>\n<p style=\"margin: 0; font-size: 14px; line-height: 1.65; color: #4A4038; text-wrap: pretty\">Today I work as an AI architect and builder: part strategist, part engineer, part teacher. A build doesn’t end at launch. It ends when your people can run it without me.</p>\n</div>\n</div>\n<div class=\"g-4\" style=\"display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 10px\">\n<div class=\"card\"><div style=\"font-weight: 600; font-size: 13px\">Systems Thinking</div><div style=\"font-size: 12px; line-height: 1.5; color: #6B5E53\">Complexity mapped into clarity.</div></div>\n<div class=\"card\"><div style=\"font-weight: 600; font-size: 13px\">End-to-End Delivery</div><div style=\"font-size: 12px; line-height: 1.5; color: #6B5E53\">Strategy, design, build, handoff.</div></div>\n<div class=\"card\"><div style=\"font-weight: 600; font-size: 13px\">AI When It Fits</div><div style=\"font-size: 12px; line-height: 1.5; color: #6B5E53\">Agents when they win, solid engineering when that does.</div></div>\n<div class=\"card\"><div style=\"font-weight: 600; font-size: 13px\">Strategy &amp; Enablement</div><div style=\"font-size: 12px; line-height: 1.5; color: #6B5E53\">Training so your team runs it.</div></div>\n</div>\n</div>\n</template>\n\n<template id=\"tpl-work\">\n<div class=\"swap\">\n<div style=\"display: flex; flex-direction: column; gap: 10px\">\n<div class=\"eyebrow\">Selected work</div>\n<h2 class=\"serif\" style=\"margin: 0; font-size: 44px; line-height: 1\">Systems running <em style=\"color: #B8466E\">in the real world.</em></h2>\n</div>\n<div style=\"display: flex; gap: 6px; flex-wrap: wrap\" data-slot=\"projectChips\"></div>\n<div style=\"position: relative; height: 200px; border-radius: 14px; border: 1px solid rgba(33,28,24,.14); background: #FFFDF9; overflow: hidden; box-shadow: 0 18px 40px -26px rgba(33,28,24,.5)\">\n<div style=\"height: 32px; display: flex; align-items: center; gap: 10px; padding: 0 12px; border-bottom: 1px solid rgba(33,28,24,.09); background: #F4EEE4\">\n<div style=\"display: flex; gap: 5px\"><span style=\"width: 8px; height: 8px; border-radius: 50%; background: rgba(33,28,24,.18)\"></span><span style=\"width: 8px; height: 8px; border-radius: 50%; background: rgba(33,28,24,.18)\"></span><span style=\"width: 8px; height: 8px; border-radius: 50%; background: rgba(33,28,24,.18)\"></span></div>\n<div class=\"mono\" data-slot=\"domain\" style=\"flex-grow: 1; height: 20px; border-radius: 6px; background: #EDE6DA; display: flex; align-items: center; padding: 0 10px; font-size: 11px; color: #4A4038\"></div>\n</div>\n<div class=\"g-prev\" style=\"position: relative; height: 168px; display: grid; grid-template-columns: 140px minmax(0, 1fr); gap: 14px; padding: 14px\">\n<div data-tint=\"bg\" style=\"border-radius: 10px; display: flex; flex-direction: column; gap: 8px; padding: 14px\">\n<div class=\"serif\" data-slot=\"mono\" style=\"font-size: 32px; line-height: 1; color: #fff\"></div>\n<div class=\"grow\" style=\"height: 6px; width: 80%; border-radius: 3px; background: rgba(255,255,255,.55)\"></div>\n<div class=\"grow\" style=\"height: 6px; width: 60%; border-radius: 3px; background: rgba(255,255,255,.4); animation-delay: .15s\"></div>\n</div>\n<div style=\"display: flex; flex-direction: column; gap: 10px\">\n<div style=\"height: 12px; width: 55%; border-radius: 6px; background: rgba(33,28,24,.14)\"></div>\n<div style=\"height: 8px; width: 80%; border-radius: 4px; background: rgba(33,28,24,.08)\"></div>\n<div style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 10px; flex-grow: 1\">\n<div class=\"bob\" style=\"border-radius: 10px; border: 1px solid rgba(33,28,24,.1); background: #FAF6EF; padding: 10px; display: flex; flex-direction: column; justify-content: flex-end\"><div data-tint=\"bg\" style=\"height: 20px; width: 50%; border-radius: 4px; opacity: .8\"></div></div>\n<div class=\"bob2\" style=\"border-radius: 10px; border: 1px solid rgba(33,28,24,.1); background: #FAF6EF; padding: 10px; display: flex; flex-direction: column; justify-content: flex-end\"><div data-tint=\"bg\" style=\"height: 36px; width: 70%; border-radius: 4px; opacity: .55\"></div></div>\n<div class=\"bob3\" style=\"border-radius: 10px; border: 1px solid rgba(33,28,24,.1); background: #FAF6EF; padding: 10px; display: flex; flex-direction: column; justify-content: flex-end\"><div data-tint=\"bg\" style=\"height: 28px; width: 40%; border-radius: 4px; opacity: .7\"></div></div>\n</div>\n</div>\n<div class=\"scan\"></div>\n</div>\n</div>\n<div style=\"display: flex; flex-direction: column; gap: 8px\">\n<div class=\"eyebrow\" data-slot=\"cat\"></div>\n<div class=\"serif w-name\" data-slot=\"name\" style=\"font-size: 34px; line-height: 1\"></div>\n<p data-slot=\"desc\" style=\"margin: 0; font-size: 14px; line-height: 1.6; color: #4A4038; text-wrap: pretty\"></p>\n</div>\n<div style=\"display: flex; align-items: center; gap: 10px; padding: 12px 14px; border-radius: 12px; background: #F6E6EC; color: #7A2B48; font-size: 13px; font-weight: 500\">\n<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 17L17 7M8 7h9v9\"></path></svg>\n<span data-slot=\"outcome\"></span>\n</div>\n<div style=\"display: flex; justify-content: space-between; align-items: center; gap: 16px; flex-wrap: wrap\">\n<div style=\"display: flex; gap: 6px; flex-wrap: wrap\" data-slot=\"tags\"></div>\n<a class=\"btn btn-p\" data-slot=\"url\" target=\"_blank\" rel=\"noopener\">View project<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M7 17L17 7M8 7h9v9\"></path></svg></a>\n</div>\n<div style=\"display: flex; gap: 18px; flex-wrap: wrap; padding-top: 14px; border-top: 1px solid rgba(33,28,24,.1); font-size: 13px\">\n<span class=\"eyebrow\" style=\"align-self: center\">Also: brand sites</span>\n<a href=\"https://www.capitalcoredance.com/\" target=\"_blank\" rel=\"noopener\">Capital Core Dance Studio →</a>\n<a href=\"https://www.epcperform.com/\" target=\"_blank\" rel=\"noopener\">Evolution Production Co →</a>\n<a href=\"https://github.com/stackd-labs\" target=\"_blank\" rel=\"noopener\">More on GitHub →</a>\n</div>\n</div>\n</template>\n\n<template id=\"tpl-services\">\n<div class=\"swap\">\n<div style=\"display: flex; flex-direction: column; gap: 10px\">\n<div class=\"eyebrow\">Three ways in</div>\n<h2 class=\"serif\" style=\"margin: 0; font-size: 44px; line-height: 1\">Build it, rescue it, <em style=\"color: #B8466E\">or bring me in.</em></h2>\n</div>\n<div class=\"g-3\" style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 12px\">\n<div style=\"padding: 20px; border-radius: 14px; border: 1px solid rgba(33,28,24,.12); background: #FFFDF9; display: flex; flex-direction: column; gap: 10px\">\n<div class=\"mono\" style=\"font-size: 11px; color: #7E5E22\">01 / NEW BUILD</div>\n<div class=\"serif\" style=\"font-size: 26px; line-height: 1\">Build your app</div>\n<p style=\"margin: 0; font-size: 13px; line-height: 1.55; color: #4A4038\">From idea to live product: data model, auth, payments, email, admin tools, and AI features that earn their place.</p>\n<div style=\"display: flex; flex-direction: column; gap: 5px; margin-top: auto; padding-top: 10px; border-top: 1px solid rgba(33,28,24,.08); font-size: 12px\"><span>Next.js + Supabase + Stripe/PayPal</span><span>Portals, dashboards, booking, billing</span><span>AI features and agents where they fit</span></div>\n</div>\n<div style=\"padding: 20px; border-radius: 14px; border: 1px solid #211C18; background: #211C18; color: #F4EEE4; display: flex; flex-direction: column; gap: 10px\">\n<div class=\"mono\" style=\"font-size: 11px; color: #D9A94E\">02 / RESCUE</div>\n<div class=\"serif\" style=\"font-size: 26px; line-height: 1\">Rescue your app</div>\n<p style=\"margin: 0; font-size: 13px; line-height: 1.55; color: #D6CCBE\">Stalled build, a vanished contractor, or an AI-generated codebase that works until it doesn’t. I audit, stabilize, and get it shipping again.</p>\n<div style=\"display: flex; flex-direction: column; gap: 5px; margin-top: auto; padding-top: 10px; border-top: 1px solid rgba(244,238,228,.14); font-size: 12px\"><span>Codebase + security audit</span><span>Auth, RLS, and payment fixes</span><span>Deploy pipeline and handoff docs</span></div>\n</div>\n<div style=\"padding: 20px; border-radius: 14px; border: 1px solid rgba(33,28,24,.12); background: #FFFDF9; display: flex; flex-direction: column; gap: 10px\">\n<div class=\"mono\" style=\"font-size: 11px; color: #7E5E22\">03 / HIRE ME</div>\n<div class=\"serif\" style=\"font-size: 26px; line-height: 1\">AI Architect / Builder</div>\n<p style=\"margin: 0; font-size: 13px; line-height: 1.55; color: #4A4038\">Contract or fractional. Agent harnesses, multi-agent orchestration, and AI workflows that run reliably in production.</p>\n<div style=\"display: flex; flex-direction: column; gap: 5px; margin-top: auto; padding-top: 10px; border-top: 1px solid rgba(33,28,24,.08); font-size: 12px\"><span>Agent harnesses + orchestration</span><span>Claude Agent SDK, MCP, tool use</span><span>Evals, guardrails, enablement</span></div>\n</div>\n</div>\n<div style=\"display: flex; flex-direction: column; gap: 12px\">\n<div class=\"eyebrow\">The process</div>\n<div class=\"g-3\" style=\"display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px\">\n<div style=\"display: flex; flex-direction: column; gap: 6px\"><div class=\"grow\" style=\"height: 2px; background: #B8466E; animation-delay: .3s\"></div><div class=\"mono\" style=\"font-size: 11px; color: #6B5E53; padding-top: 4px\">01</div><div style=\"font-weight: 600; font-size: 14px\">Discovery or Audit</div><div style=\"font-size: 12px; line-height: 1.5; color: #6B5E53\">Map the business, or audit the codebase and say plainly what it needs.</div></div>\n<div style=\"display: flex; flex-direction: column; gap: 6px\"><div class=\"grow\" style=\"height: 2px; background: #A9803A; animation-delay: .6s\"></div><div class=\"mono\" style=\"font-size: 11px; color: #6B5E53; padding-top: 4px\">02</div><div style=\"font-weight: 600; font-size: 14px\">Build</div><div style=\"font-size: 12px; line-height: 1.5; color: #6B5E53\">Design and develop, with you in the loop at every milestone.</div></div>\n<div style=\"display: flex; flex-direction: column; gap: 6px\"><div class=\"grow\" style=\"height: 2px; background: #211C18; animation-delay: .9s\"></div><div class=\"mono\" style=\"font-size: 11px; color: #6B5E53; padding-top: 4px\">03</div><div style=\"font-weight: 600; font-size: 14px\">Launch &amp; Iterate</div><div style=\"font-size: 12px; line-height: 1.5; color: #6B5E53\">Ship, measure, and refine until it works exactly as intended.</div></div>\n</div>\n</div>\n</div>\n</template>\n\n<template id=\"tpl-stack\">\n<div class=\"swap\">\n<div style=\"display: flex; flex-direction: column; gap: 10px\">\n<div class=\"eyebrow\">The right tool for each job</div>\n<h2 class=\"serif\" data-slot=\"tabName\" style=\"margin: 0; font-size: 44px; line-height: 1\"></h2>\n</div>\n<div style=\"display: flex; gap: 6px; flex-wrap: wrap\" data-slot=\"tabChips\"></div>\n<div class=\"g-2\" style=\"display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 10px\" data-slot=\"items\"></div>\n<p style=\"margin: 0; font-size: 13px; line-height: 1.55; color: #6B5E53\">Every tool is chosen on purpose. The goal is always a system that’s lean, secure, and built to last.</p>\n</div>\n</template>\n\n<template id=\"tpl-clients\">\n<div class=\"swap\">\n<div style=\"display: flex; flex-direction: column; gap: 10px\">\n<div class=\"eyebrow\">Proof, in their words</div>\n<h2 class=\"serif\" style=\"margin: 0; font-size: 44px; line-height: 1\">What clients <em style=\"color: #B8466E\">say.</em></h2>\n</div>\n<div style=\"display: flex; gap: 12px; align-items: flex-start\">\n<div class=\"serif\" style=\"width: 42px; height: 42px; border-radius: 50%; background: #211C18; color: #F4EEE4; display: grid; place-items: center; font-size: 20px; flex-shrink: 0\">V</div>\n<div style=\"display: flex; flex-direction: column; gap: 6px\"><div style=\"padding: 14px 16px; border-radius: 4px 16px 16px 16px; background: #FFFDF9; border: 1px solid rgba(33,28,24,.1); font-size: 14px; line-height: 1.55\">“Chanel replaced three separate tools with one platform that actually fits how we work. Placements, billing, and inventory finally live in one place, and her training meant our team was running it confidently from day one.”</div><div class=\"mono\" style=\"font-size: 11px; color: #6B5E53\">Villa Concierge Co · Insurance Operations Platform</div></div>\n</div>\n<div style=\"display: flex; gap: 12px; align-items: flex-start\">\n<div class=\"serif\" style=\"width: 42px; height: 42px; border-radius: 50%; background: #B8466E; color: #fff; display: grid; place-items: center; font-size: 20px; flex-shrink: 0\">C</div>\n<div style=\"display: flex; flex-direction: column; gap: 6px\"><div style=\"padding: 14px 16px; border-radius: 4px 16px 16px 16px; background: #FFFDF9; border: 1px solid rgba(33,28,24,.1); font-size: 14px; line-height: 1.55\">“She understood our studio before she touched the code. The site she built is fast, beautiful, and made for enrollment, and inquiries climbed within the first month of launch.”</div><div class=\"mono\" style=\"font-size: 11px; color: #6B5E53\">Capital Core Dance Studio · Midlothian, VA</div></div>\n</div>\n<div style=\"display: flex; gap: 12px; align-items: flex-start\">\n<div class=\"serif\" style=\"width: 42px; height: 42px; border-radius: 50%; background: #EFE2C8; color: #5C4418; display: grid; place-items: center; font-size: 20px; flex-shrink: 0\">E</div>\n<div style=\"display: flex; flex-direction: column; gap: 6px\"><div style=\"padding: 14px 16px; border-radius: 4px 16px 16px 16px; background: #FFFDF9; border: 1px solid rgba(33,28,24,.1); font-size: 14px; line-height: 1.55\">“Full brand site shipped in two weeks with zero revision rounds. Chanel just got it, the work carried the weight a performance brand needs without us having to spell it out.”</div><div class=\"mono\" style=\"font-size: 11px; color: #6B5E53\">Evolution Production Co · Touring Ice &amp; Dance, DMV</div></div>\n</div>\n</div>\n</template>\n\n<template id=\"tpl-contact\">\n<div class=\"swap\">\n<div style=\"display: flex; flex-direction: column; gap: 10px\">\n<div class=\"eyebrow\">End of the line, start of yours</div>\n<h2 class=\"serif\" style=\"margin: 0; font-size: 44px; line-height: 1\">Building, stuck, or hiring? <em style=\"color: #B8466E\">Let’s talk.</em></h2>\n<p style=\"margin: 0; font-size: 14px; line-height: 1.55; color: #4A4038\">A new app, one that stalled, or a role on your team. Tell me what you have and where it hurts. I reply within 24 to 48 hours.</p>\n</div>\n<div class=\"g-2\" style=\"display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px\">\n<div class=\"field\"><label for=\"cf-name\">Name</label><input id=\"cf-name\" type=\"text\" autocomplete=\"name\"></div>\n<div class=\"field\"><label for=\"cf-email\">Email</label><input id=\"cf-email\" type=\"email\" autocomplete=\"email\"></div>\n</div>\n<div class=\"field\"><label for=\"cf-msg\">Message</label><textarea id=\"cf-msg\" rows=\"4\" placeholder=\"What are you building, what is broken, or what is the role?\"></textarea></div>\n<div class=\"send-row\" style=\"display: flex; justify-content: space-between; align-items: center; gap: 12px\">\n<button class=\"btn btn-p\" data-action=\"send\" id=\"cf-send\">Send message<svg width=\"16\" height=\"16\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M22 2L11 13M22 2l-7 20-4-9-9-4 20-7z\"></path></svg></button>\n<a href=\"mailto:chanel@stackdstudiosai.com\" class=\"mono\" style=\"font-size: 12px\">chanel@stackdstudiosai.com</a>\n</div>\n<span class=\"jr-status\" id=\"cf-status\" aria-live=\"polite\"></span>\n<div style=\"display: flex; gap: 8px; flex-wrap: wrap; padding-top: 14px; border-top: 1px solid rgba(33,28,24,.1)\">\n<a class=\"soc\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://github.com/stackd-labs\">GitHub</a>\n<a class=\"soc\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.linkedin.com/in/chanel-hicks-gray-ms-lpc-r-b673a720\">LinkedIn</a>\n<a class=\"soc\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.threads.net/@chanelhicksgray\">Threads</a>\n<a class=\"soc\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.instagram.com/chanelhicksgray\">Instagram</a>\n<a class=\"soc\" target=\"_blank\" rel=\"noopener noreferrer\" href=\"https://www.tiktok.com/@chanelhicksgray\">TikTok</a>\n</div>\n</div>\n</template>";
